contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 a, uint256 e) public {
        c.AdjustBetAmounts(a); if (__ESBMC_reverted()) return;
        c.AdjustDifficulty(e); if (__ESBMC_reverted()) return;
        assert(c.currentBetLimit() == a && c.currentDifficulty() == e);
    }
    receive() external payable {}
}

