// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 a, uint256 e) internal {
        try c.AdjustBetAmounts(a) {} catch { return; }
        try c.AdjustDifficulty(e) {} catch { return; }
        assertTrue(c.currentBetLimit() == a && c.currentDifficulty() == e);
    }

    function testFuzz_run(uint256 a, uint256 e) public {
        _run(a, e);
    }

    receive() external payable {}
}
